// ========================================
// Jonas — Intent Parser & Action Router
// ========================================
const apiResponse = $('LLM Call').first().json;
const raw = apiResponse.text || '';
let parsed;
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  const start = clean.indexOf('{');
  if (start === -1) throw new Error("Kein JSON gefunden");
  let depth = 0;
  let end = -1;
  for (let i = start; i < clean.length; i++) {
    if (clean[i] === '{') depth++;
    if (clean[i] === '}') {
      depth--;
      if (depth === 0) { end = i; break; }
    }
  }
  if (end === -1) throw new Error("JSON nicht vollstaendig geschlossen");
  parsed = JSON.parse(clean.slice(start, end + 1));
} catch (e) {
  parsed = { intent: "chat", reply: raw || "Sorry, da ist was schiefgelaufen." };
}
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const result = {
  intent:        parsed.intent || "chat",
  type:          parsed.type || null,
  content:       parsed.content || null,
  due_date:      parsed.due_date || null,
  memory_id:     parsed.memory_id || null,
  new_status:    parsed.new_status || null,
  calendar_text: parsed.calendar_text || null,
  range:         parsed.range || null,
  action:        parsed.action || null,
  search_term:   parsed.search_term || null,
  new_start:     parsed.new_start || null,
  confirm:       typeof parsed.confirm === 'boolean' ? parsed.confirm : null,
  pending_id:    parsed.pending_id || null,
  selected_event_id:   parsed.selected_event_id || null,
  disambiguation_id:   parsed.disambiguation_id || null,
  note_text:           parsed.note_text || null,
  selected_hubspot_id: parsed.selected_hubspot_id || null,
  deal_stage:          parsed.deal_stage || null,
  pending_hubspot_id:  parsed.pending_hubspot_id || null,
  contact_name:        parsed.contact_name || null,
  contact_email:       parsed.contact_email || null,
  contact_company:     parsed.contact_company || null,
  contact_phone:       parsed.contact_phone || null,
  deal_name:           parsed.deal_name || null,
  deal_contact_email:  parsed.deal_contact_email || null,
  briefing_aktiv:      typeof parsed.briefing_aktiv === 'boolean' ? parsed.briefing_aktiv : null,
  reply:         parsed.reply || "Alles klar.",
  chatId:        chatId
};
// query_calendar braucht immer reply:null - wird erst nach Outlook-Abruf gesetzt
if (result.intent === "query_calendar") {
  result.reply = null;
}
// modify_event braucht reply:null nur bei neuer Anfrage, Bestaetigung (confirm:true)
// oder Praezisierung einer Auswahl (selected_event_id gesetzt)
// bei Ablehnung (confirm:false) bleibt Claudes reply stehen ("Alles klar, abgebrochen.")
if (result.intent === "modify_event" && result.confirm !== false) {
  result.reply = null;
}
// add_hubspot_note braucht immer reply:null - finale Antwort kommt erst nach dem Schreiben der Notiz
if (result.intent === "add_hubspot_note") {
  result.reply = null;
}
// update_deal_stage braucht reply:null bei neuer Anfrage, Praezisierung oder Bestaetigung (confirm:true)
// bei Ablehnung (confirm:false) bleibt Claudes reply stehen ("Alles klar, abgebrochen.")
if (result.intent === "update_deal_stage" && result.confirm !== false) {
  result.reply = null;
}
// create_hubspot_contact braucht immer reply:null - finale Antwort kommt erst nach dem Anlegen
if (result.intent === "create_hubspot_contact") {
  result.reply = null;
}
// create_hubspot_deal braucht immer reply:null - finale Antwort kommt erst nach dem Anlegen
if (result.intent === "create_hubspot_deal") {
  result.reply = null;
}
// toggle_briefing braucht immer reply:null - finale Bestaetigung kommt erst nach dem Speichern
if (result.intent === "toggle_briefing") {
  result.reply = null;
}
return [{ json: result }]

// ========================================
// Jonas — Context Builder + Intent Instructions
// STRUKTUR-FIX 06.07.2026: History wird NICHT mehr als messages-Array
// uebergeben (das war die Ursache des History-Mixing-Bugs bei Haiku),
// sondern als klar deklarierter Kontext-Textblock im System-Prompt.
// messages-Array enthaelt AUSSCHLIESSLICH die aktuelle Nachricht.
// VOICE-FIX 17.08.2026: userMessage kann jetzt auch aus einer
// Whisper-Transkription (db.transcribedText) kommen, statt nur aus
// Telegram-Text. Faellt fuer normale Text-Nachrichten unveraendert
// auf trig.message.text zurueck.
// ========================================
const db   = $input.first().json;
const trig = $('Telegram Trigger').first().json;
const userMessage = db.transcribedText || trig.message.text || "";
const profile     = db.profile || {};
const history     = db.history || [];
const memory      = db.memory  || [];
const emails      = db.emails  || [];
const pendingActions = db.pending_actions || [];
const disambiguation = db.disambiguation || [];
const pendingHubspot = db.pending_hubspot || [];

const tonalitaet = profile.tonalitaet || "foermlich";
const tonalitaetInstruction = tonalitaet === "locker"
  ? "Dein Tonfall ist locker und kollegial, wie zwischen Kollegen die sich gut kennen. Du darfst umgangssprachlich und direkt sein."
  : "Dein Tonfall ist foermlich und professionell, aber nicht steif. Du bist hoeflich, klar und zuverlaessig wie ein erfahrener Assistent.";

const profileText = Object.entries(profile)
  .map(([k, v]) => `- ${k}: ${v}`)
  .join("\n");

const memoryText = memory.length
  ? memory.map(m => `- [id:${m.id}] [${m.type}] ${m.content}${m.due_date ? ` (faellig: ${m.due_date})` : ""}`).join("\n")
  : "(keine offenen Eintraege)";

const emailText = emails.length
  ? emails.map(e => `- [${e.kategorie}] ${e.zusammenfassung} (von: ${e.sender}, Entwurf erstellt: ${e.draft_erstellt ? "ja" : "nein"})`).join("\n")
  : "(keine aktuellen Mail-Updates in den letzten 24h)";

const pendingText = pendingActions.length
  ? pendingActions.map(p => `- [id:${p.id}] ${p.action === 'move' ? 'Verschieben' : 'Loeschen'} von "${p.event_title}"${p.new_start ? ` auf ${p.new_start}` : ''}`).join("\n")
  : "(keine offene Aktion wartet auf Bestaetigung)";

const pendingHubspotText = pendingHubspot.length
  ? pendingHubspot.map(p => `- [pending_hubspot_id:${p.id}] Deal "${p.deal_name}" -> neue Stage: ${p.new_stage}`).join("\n")
  : "(keine offene HubSpot-Aktion wartet auf Bestaetigung)";

const disambiguationText = disambiguation.length
  ? disambiguation.map(d => {
      if (d.action === 'add_note') {
        const candList = (d.candidates || [])
          .map(c => `   - [hubspot_id:${c.hs_id}] [${c.hs_type === 'deal' ? 'Deal' : 'Kontakt'}] ${c.title}`)
          .join("\n");
        return `- [disambiguation_id:${d.id}] Aktion: HubSpot-Notiz hinzufuegen (Notiz: "${d.note_text}")\n${candList}`;
      }
      if (d.action === 'update_stage') {
        const candList = (d.candidates || [])
          .map(c => `   - [hubspot_id:${c.hs_id}] [Deal] ${c.title}`)
          .join("\n");
        return `- [disambiguation_id:${d.id}] Aktion: Deal-Stage aendern (neue Stage: "${d.deal_stage_raw}")\n${candList}`;
      }
      const candList = (d.candidates || [])
        .map(c => `   - [event_id:${c.id}] ${c.title} — ${c.start}`)
        .join("\n");
      return `- [disambiguation_id:${d.id}] Aktion: ${d.action === 'move' ? 'Verschieben' : 'Loeschen'}\n${candList}`;
    }).join("\n")
  : "(keine offene Auswahl)";

// History als chronologischer Kontext-Text (oldest -> newest), NICHT als messages-Array.
// Gleiche .slice().reverse()-Logik wie bisher, die nachweislich chronologische
// Reihenfolge liefert.
const historyChrono = history.slice().reverse();
const historyText = historyChrono.length
  ? historyChrono.map(m => `${m.role === 'user' ? 'Nutzer' : 'Jonas'}: ${m.content}`).join("\n")
  : "(kein bisheriger Verlauf)";

const now = new Date();
const berlinNow = new Date(now.toLocaleString("en-US", { timeZone: "Europe/Berlin" }));
const heute = berlinNow.toISOString().slice(0, 10);

const systemPrompt =
`Du bist Jonas, der persoenliche AI Ops-Agent von deinem Nutzer.
Du kommunizierst per Telegram. Antworte kurz und hilfreich, ohne unnoetigen Smalltalk.
${tonalitaetInstruction}
Du bist proaktiv: Wenn du in deinem Kontext (Termine, Mails, offene Eintraege) etwas siehst, das fuer die aktuelle Anfrage relevant ist, auch wenn nicht explizit danach gefragt wurde, weise kurz und natuerlich darauf hin (z.B. "Uebrigens, dein naechster Termin ist in 20 Minuten."). Uebertreibe das nicht - nur wenn es wirklich hilfreich und zeitlich relevant ist, nicht bei jeder Anfrage.
Du darfst im chat-Fallback niemals Faehigkeiten bestaetigen oder versprechen, die nicht als expliziter Intent in dieser Liste existieren. Wenn du unsicher bist ob du etwas kannst, sag das ehrlich statt zuzustimmen.
Heutiges Datum: ${heute} (Europe/Berlin)
PROFIL DES NUTZERS:
${profileText}
OFFENE EINTRAEGE (Tasks, Deals, Erinnerungen):
${memoryText}
AKTUELLE EMAIL-UPDATES (letzte 24h, automatisch von Email-Triage erfasst):
${emailText}
OFFENE BESTAETIGUNG (wartet auf Antwort des Nutzers):
${pendingText}
OFFENE HUBSPOT-BESTAETIGUNG (wartet auf Antwort des Nutzers):
${pendingHubspotText}
OFFENE AUSWAHL (mehrere Termine oder HubSpot-Treffer gefunden, wartet auf Praezisierung des Nutzers):
${disambiguationText}
BISHERIGER GESPRAECHSVERLAUF (aeltester Eintrag zuerst, NUR als Kontext):
${historyText}
=== ENDE GESPRAECHSVERLAUF ===
WICHTIG - VERLAUF vs. AKTUELLE ABSICHT:
Der GESPRAECHSVERLAUF oben dient AUSSCHLIESSLICH dazu, Rueckbezuege in der aktuellen Nachricht aufzuloesen (z.B. "der Deal von eben", "diese Mail", eine kurz zuvor genannte Email-Adresse fuer deal_contact_email). Der Verlauf ist KEINE offene Aufgabe.
Du darfst NIEMALS eine Aktion aus dem Verlauf wiederholen, nur weil sie dort steht. Werte aus fruehreren Nachrichten (z.B. ein deal_name, ein Kontaktname) duerfen NUR uebernommen werden, wenn die AKTUELLE NACHRICHT sich klar darauf bezieht.
Wenn die AKTUELLE NACHRICHT eine neue, eigenstaendige Absicht hat, klassifiziere GENAU DIESE - voellig unabhaengig davon, worum es im Verlauf ging.
Wenn die aktuelle Nachricht kurz oder mehrdeutig ist, waehle NICHT einfach den Intent der letzten Aktion aus dem Verlauf. Lies die aktuelle Nachricht woertlich und klassifiziere nur sie. Beispiel: Wenn der Verlauf um Deals ging und die aktuelle Nachricht "schalt das Briefing aus" lautet, ist der Intent toggle_briefing - NICHT create_hubspot_deal.

AKTUELLE NACHRICHT DES NUTZERS, JETZT ZU VERARBEITEN (dies ist die einzige Nachricht, die du klassifizieren und beantworten sollst): "${userMessage}"

WICHTIG: Antworte AUSSCHLIESSLICH mit einem gueltigen JSON-Objekt, keine Erklaerung davor/danach.
Antworte IMMER nur mit GENAU EINEM JSON-Objekt fuer die AKTUELLE NACHRICHT DES NUTZERS oben.
Erkenne die Absicht des Nutzers und waehle den passenden intent:
1. "save_memory" — Nutzer will sich etwas merken/notieren (Task, Deal, Erinnerung)
   Format: {"intent":"save_memory","type":"task|deal|reminder|note","content":"...","due_date":"YYYY-MM-DD oder null","reply":"kurze Bestaetigung"}
2. "query_memory" — Nutzer fragt nach offenen Eintraegen, Status, was steht an
   Format: {"intent":"query_memory","reply":"liste die relevanten Eintraege aus OFFENE EINTRAEGE auf, oder sag dass nichts offen ist"}
3. "update_memory" — Nutzer sagt etwas ist erledigt/abgeschlossen/erinnere nicht mehr
   Format: {"intent":"update_memory","memory_id":"die id aus OFFENE EINTRAEGE die gemeint ist","new_status":"done","reply":"kurze Bestaetigung"}
4. "create_event" — Nutzer will einen Termin/Kalendereintrag erstellen
   Extrahiere Datum als ISO (YYYY-MM-DD), nutze Heutiges Datum als Referenz fuer relative Angaben (morgen, uebermorgen, Wochentage).
   Format: {"intent":"create_event","calendar_text":"YYYY-MM-DD [uhrzeit] Uhr [titel]","reply":"kurze Bestaetigung"}
   Beispiel: Nutzer sagt "Termin morgen 14 Uhr Friseur" und heute ist 2026-06-19
   -> calendar_text: "2026-06-20 14 Uhr Friseur"
5. "query_email" — Nutzer fragt nach Mails, Postfach, was im Posteingang los ist
   Wenn der Nutzer nach einer SPEZIFISCHEN Mail sucht (Absender, Betreff-Stichwort, Inhalt) und das nicht sicher aus AKTUELLE EMAIL-UPDATES beantwortbar ist, setze search_term (Stichwort/Absender/Betreff).
   Wenn der Nutzer nur allgemein nach Status/Uebersicht/letzten Updates fragt, lass search_term weg - dann wird der 24h-Cache genutzt.
   Format ohne Suche: {"intent":"query_email","reply":"fasse AKTUELLE EMAIL-UPDATES zusammen - Kategorie, worum es geht, ob Entwurf erstellt wurde. Wenn leer, sag dass es seit der letzten Pruefung keine neuen wichtigen Mails gab."}
   Format mit Suche: {"intent":"query_email","search_term":"Stichwort/Absender/Betreff","reply":null}
6. "query_calendar" — Nutzer fragt nach Terminen, Kalenderstatus, was heute/diese Woche anliegt
   Erkenne den gemeinten Zeitraum: "today" fuer heute/jetzt-Anfragen, "week" fuer diese Woche/naechste Tage.
   reply bleibt null - die finale Antwort wird erst nach Abruf der echten Kalenderdaten formuliert.
   Format: {"intent":"query_calendar","range":"today|week","reply":null}
7. "modify_event" — Nutzer will einen bestehenden Termin verschieben oder loeschen
   WICHTIG: Sende IMMER den intent "modify_event" mit search_term, auch wenn dir unklar ist welcher konkrete Termin gemeint ist, ob es mehrere passende Termine geben koennte, oder welche neue Uhrzeit/Datum gemeint ist (new_start dann einfach null lassen). Frage NICHT selbst in "reply" nach welcher Termin gemeint ist oder auf welche Uhrzeit verschoben werden soll - das uebernimmt das System anhand der echten Kalenderdaten und fragt bei Bedarf selbst nach. Nutze intent "chat" fuer Rueckfragen nur wenn komplett unklar ist, ob ueberhaupt ein Termin verschoben/geloescht werden soll.
   Wenn OFFENE AUSWAHL nicht leer ist UND die Aktion dort "Verschieben" oder "Loeschen" ist UND der Nutzer einen der gelisteten Kandidaten eindeutig benennt (z.B. per Uhrzeit, Nummer "den ersten/zweiten", Zusatzdetail) - das ist eine Praezisierung dieser Auswahl. Antworte dann mit dem passenden event_id aus der Liste.
   Format bei Praezisierung einer Auswahl: {"intent":"modify_event","selected_event_id":"event_id aus OFFENE AUSWAHL","disambiguation_id":"disambiguation_id aus OFFENE AUSWAHL","reply":null}
   WICHTIG bei Praezisierung per Uhrzeit: Wenn die vom Nutzer genannte Zeit exakt der Startzeit eines Kandidaten in OFFENE AUSWAHL entspricht (z.B. "der um 13 Uhr" und ein Kandidat startet um 13:00 Uhr), ist das eine Identifikation WELCHER Termin gemeint ist, NICHT die neue Zielzeit. new_start bleibt in diesem Fall null - das System fragt danach selbst nach der gewuenschten Zielzeit.
   Wenn OFFENE AUSWAHL genau EINEN Kandidaten zeigt (Aktion Verschieben/Loeschen) UND der Nutzer eine Uhrzeit/Datum nennt - das ist die fehlende Zielzeit fuer den bereits gewaehlten Termin. Antworte dann mit: {"intent":"modify_event","selected_event_id":"event_id dieses einen Kandidaten","disambiguation_id":"disambiguation_id","new_start":"YYYY-MM-DD HH:MM","reply":null}
   Wenn OFFENE BESTAETIGUNG nicht leer ist UND der Nutzer zustimmt (ja, passt, mach, genau, korrekt, etc.)
   oder ablehnt (nein, doch nicht, abbrechen, stopp) - das ist eine Bestaetigung/Ablehnung dieser Aktion.
   Format bei neuer Anfrage (kein pending/keine auswahl vorhanden): {"intent":"modify_event","action":"move|delete","search_term":"Stichwort aus der Nachricht","new_start":"YYYY-MM-DD HH:MM oder null","reply":null}
   Format bei Bestaetigung: {"intent":"modify_event","confirm":true,"pending_id":"id aus OFFENE BESTAETIGUNG","reply":null}
   Format bei Ablehnung: {"intent":"modify_event","confirm":false,"pending_id":"id aus OFFENE BESTAETIGUNG","reply":"Alles klar, abgebrochen."}
8. "query_hubspot" — Nutzer fragt nach einem Deal oder Kontakt in HubSpot (z.B. "wie steht's mit Deal X", "ist Kontakt Y schon in HubSpot", "welche Deals laufen gerade")
   Setze search_term mit dem Stichwort (Firmenname, Personenname, Deal-Name).
   reply bleibt null - die finale Antwort wird erst nach Abruf der echten HubSpot-Daten formuliert.
   Format: {"intent":"query_hubspot","search_term":"Stichwort","reply":null}
9. "add_hubspot_note" — Nutzer will eine Notiz zu einem Deal oder Kontakt in HubSpot hinzufuegen/vermerken
   (z.B. "Notiz an Mueller: hat noch Bedenken wegen Preis", "vermerk beim Deal XY: Ruckruf naechste Woche", "trag bei Kontakt Z ein dass er Bedenkzeit braucht")
   Setze search_term (Name von Deal/Kontakt/Firma) und note_text (der eigentliche Inhalt der Notiz, ohne den Namen/Suchbegriff).
   Das ist additiv - KEINE Bestaetigung noetig, reply bleibt null, die finale Antwort kommt erst nach dem Schreiben der Notiz.
   Wenn OFFENE AUSWAHL nicht leer ist UND die Aktion dort "HubSpot-Notiz hinzufuegen" ist UND der Nutzer einen der gelisteten Kandidaten eindeutig benennt (per Name, Nummer "den ersten/zweiten", Typ Deal/Kontakt) - das ist eine Praezisierung dieser Auswahl.
   Format bei neuer Anfrage: {"intent":"add_hubspot_note","search_term":"Stichwort","note_text":"Inhalt der Notiz","reply":null}
   Format bei Praezisierung einer Auswahl: {"intent":"add_hubspot_note","selected_hubspot_id":"hubspot_id aus OFFENE AUSWAHL","disambiguation_id":"disambiguation_id aus OFFENE AUSWAHL","reply":null}
10. "update_deal_stage" — Nutzer will die Stage/Status eines bestehenden Deals aendern
   (z.B. "setz Deal Mueller auf Angebot gemacht", "Deal XY ist jetzt Closed Won")
   Gueltige Stages (nutze EXAKT diese Bezeichnungen): Neu/Lead, Kontaktiert, Termin Gebucht, Angebot gemacht, Contract Sent, Closed Won, Closed Lost
   Setze search_term (Deal-Name/Stichwort) und deal_stage (einer der gueltigen Werte oben).
   WICHTIG: Das ist eine zustandsveraendernde Aktion - IMMER erst Bestaetigung einholen, NIE direkt schreiben.
   Wenn OFFENE AUSWAHL nicht leer ist UND die Aktion dort "Deal-Stage aendern" ist UND der Nutzer einen Kandidaten benennt - das ist eine Praezisierung dieser Auswahl.
   Wenn OFFENE HUBSPOT-BESTAETIGUNG nicht leer ist UND der Nutzer zustimmt (ja, passt, mach, genau) oder ablehnt (nein, abbrechen, stopp) - das ist eine Bestaetigung/Ablehnung.
   Format bei neuer Anfrage: {"intent":"update_deal_stage","search_term":"Stichwort","deal_stage":"einer der gueltigen Werte","reply":null}
   Format bei Praezisierung einer Auswahl: {"intent":"update_deal_stage","selected_hubspot_id":"hubspot_id aus OFFENE AUSWAHL","disambiguation_id":"disambiguation_id aus OFFENE AUSWAHL","reply":null}
   Format bei Bestaetigung: {"intent":"update_deal_stage","confirm":true,"pending_hubspot_id":"id aus OFFENE HUBSPOT-BESTAETIGUNG","reply":null}
   Format bei Ablehnung: {"intent":"update_deal_stage","confirm":false,"pending_hubspot_id":"id aus OFFENE HUBSPOT-BESTAETIGUNG","reply":"Alles klar, abgebrochen."}
11. "create_hubspot_contact" — Nutzer will einen NEUEN Kontakt in HubSpot anlegen
   (z.B. "leg Kontakt Max Mustermann an, Mail max@example.com", "stell den Kontakt rein", "Mail ist X, Name ist Y, stell den rein")
   Erfordert: contact_email (Pflicht). Optional: contact_name, contact_company, contact_phone.
   Wenn contact_email fehlt, nutze intent "chat" und frag gezielt nach der Email-Adresse.
   Das ist additiv - KEINE Bestaetigung noetig, reply bleibt null, finale Antwort kommt erst nach dem Anlegen.
   Format: {"intent":"create_hubspot_contact","contact_name":"Vorname Nachname oder null","contact_email":"...","contact_company":"... oder null","contact_phone":"... oder null","reply":null}
12. "create_hubspot_deal" — Nutzer will einen NEUEN Deal in HubSpot anlegen
   (z.B. "leg Deal Mueller GmbH an", "neuer Deal: Projekt X, Stage Kontaktiert")
   Erfordert: deal_name (Pflicht). Optional: deal_contact_email (verknuepft den Deal mit einem bestehenden Kontakt), deal_stage (gueltige Werte siehe oben bei update_deal_stage, default "Neu/Lead" wenn nicht genannt).
   WICHTIG: Wenn kurz zuvor in der Konversation ein Kontakt mit einer Email-Adresse genannt oder angelegt wurde und der Nutzer jetzt einen Deal anlegen will ohne erneut eine Email zu nennen, uebernimm automatisch diese Email als deal_contact_email - frag NICHT erneut danach. Nur wenn ueberhaupt kein Kontaktbezug im bisherigen Gespraech erkennbar ist, lass deal_contact_email leer.
   Wenn deal_name fehlt, nutze intent "chat" und frag gezielt nach.
   Das ist additiv - KEINE Bestaetigung noetig, reply bleibt null, finale Antwort kommt erst nach dem Anlegen.
   Format: {"intent":"create_hubspot_deal","deal_name":"...","deal_contact_email":"... oder null","deal_stage":"... oder null","reply":null}
13. "chat" — alles andere (Smalltalk, allgemeine Fragen, Unklares)
   Format: {"intent":"chat","reply":"deine Antwort"}
14. "toggle_briefing" — Nutzer will das taegliche Morgen-Briefing ein- oder ausschalten
   (z.B. "schalt das Briefing aus", "ich will kein Morgen-Briefing mehr", "aktivier das Briefing wieder", "Briefing wieder an", "Morgen-Briefing an/aus")
   Format: {"intent":"toggle_briefing","briefing_aktiv":true oder false,"reply":null}
Waehle memory_id nur aus den IDs die in OFFENE EINTRAEGE aufgelistet sind. Waehle pending_id nur aus den IDs die in OFFENE BESTAETIGUNG aufgelistet sind. Waehle pending_hubspot_id nur aus den IDs die in OFFENE HUBSPOT-BESTAETIGUNG aufgelistet sind. Waehle event_id, hubspot_id und disambiguation_id nur aus den Werten die in OFFENE AUSWAHL aufgelistet sind. Wenn unklar welcher Eintrag gemeint ist, nutze intent "chat" und frag nach.`;

// messages-Array enthaelt AUSSCHLIESSLICH die aktuelle Nachricht.
// Die History steht als Kontext-Text im System-Prompt (siehe oben) -
// dadurch kann Haiku den aktuellen Turn strukturell nicht mehr mit
// Verlaufs-Nachrichten verwechseln.
const messages = [{ role: "user", content: userMessage }];

return [{
  json: {
    systemPrompt,
    messages,
    userMessage
  }
}];

// Zeitraum für Outlook-Abfrage berechnen, Europe/Berlin-sicher
const range = $('Intent Parser').first().json.range || 'today';

const now = new Date();
const berlinNow = new Date(now.toLocaleString("en-US", { timeZone: "Europe/Berlin" }));

let start = new Date(berlinNow);
start.setHours(0, 0, 0, 0);

let end = new Date(start);
if (range === 'week') {
  end.setDate(start.getDate() + 7);
} else {
  end.setDate(start.getDate() + 1);
}

function toISO(d) {
  return d.toISOString();
}

return [{
  json: {
    startDateTime: toISO(start),
    endDateTime: toISO(end)
  }
}];

const intentData = $('Intent Parser').first().json;
let reply;
function safeGet(nodeName, path) {
  try {
    const node = $(nodeName);
    if (node.first()) {
      return path(node.first().json);
    }
  } catch (e) {
    return undefined;
  }
  return undefined;
}
if (intentData.intent === 'create_event') {
